function file = link_write_config(P, file)
%LINK_WRITE_CONFIG  Write the numbers the Python side and the firmware check need, from twin_params (the single
%   source), as JSON. file = link_write_config(P, file); default file = link/link_config.json.
%   Read by bridge.py (repeat timing), fake_bot.py (robot model + controller), aruco_node.py (markers, geometry,
%   timing) and py/check_numbers.py (compares firmware/zadp_bot/include/config.h with it). Regenerated by
%   link_launch and run_real on every start, so it never lags twin_params.
if nargin < 2 || isempty(file)
    file = fullfile(fileparts(mfilename('fullpath')), 'link_config.json');
end
C.source = 'twin3d/params/twin_params.m (generated by link_write_config.m, do not edit)';
C.mqtt = P.mqtt;
C.link = P.link;
C.bot = P.bot;
C.ctrl = P.ctrl;
C.brain = struct('turnTolDeg', P.brain.turnTolDeg, 'dumpTolDeg', P.brain.dumpTolDeg, ...
    'minTurnRate', P.brain.minTurnRate, 'slideDist', P.brain.slideDist, 'lookahead', P.brain.lookahead, ...
    'parking', P.brain.parking);
C.cam = P.cam;
C.truck = struct('dumpTime', P.truck.dumpTime);
C.sim = struct('dt', P.sim.dt);
txt = jsonencode(C, 'PrettyPrint', true);
fid = fopen(file, 'w');
if fid < 0, error('link:config', 'cannot write %s', file); end
fwrite(fid, txt);
fclose(fid);
end
